css:
.hr-page{--ink:#17202a;--blue:#2563eb;--blue-deep:#1d4ed8;--tint:#eff5ff;--gray:#c3cbd6;--line:#dfe5ec;--mute:#5a6675;background:#fff;color:var(--ink);font-family:var(--page-sans),'Pretendard','Noto Sans KR','Apple SD Gothic Neo',sans-serif;font-size:16.5px;line-height:1.75;word-break:keep-all;overflow-wrap:break-word;font-variant-numeric:tabular-nums;-webkit-font-smoothing:antialiased}
.hr-page *,.hr-page *::before,.hr-page *::after{box-sizing:border-box}
.hr-page h1,.hr-page h2,.hr-page h3,.hr-page p,.hr-page ul,.hr-page ol,.hr-page dl,.hr-page dd,.hr-page figure{margin:0;padding:0}
.hr-page ul,.hr-page ol{list-style:none}
.hr-wrap{display:block;max-width:1040px;margin:0 auto;padding:0 24px}
.hr-hero{display:block;padding:72px 0 56px}
.hr-who{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 14px;margin-bottom:28px}
.hr-name{font-size:20px;font-weight:750}
.hr-role{font-size:16px;color:var(--mute)}
.hr-h1{font-size:clamp(32px,6vw,52px);line-height:1.2;font-weight:800;letter-spacing:-.025em;max-width:16em}
.hr-lead{margin-top:20px;max-width:34em;color:#2b3745}
.hr-ruler{display:block;margin-top:44px;padding:28px 0 0}
.hr-plot{display:block;position:relative;padding:0;background-image:linear-gradient(to right,var(--line) 1px,transparent 1px);background-size:25% 100%;background-repeat:repeat-x;border-right:1px solid var(--line)}
.hr-bar{display:block;height:52px;margin:0 0 14px;transform-origin:left center;border-radius:0 4px 4px 0;position:relative}
.hr-bar span{display:block;position:absolute;left:14px;top:50%;transform:translateY(-50%);font-size:15px;font-weight:700;white-space:nowrap}
.hr-bar-before{width:95%;background:var(--gray);color:var(--ink);animation:hr-grow 1.1s cubic-bezier(.2,.7,.2,1) .2s both}
.hr-bar-after{width:47.5%;background:var(--blue);color:#fff;margin-bottom:0;animation:hr-grow .9s cubic-bezier(.2,.7,.2,1) 1.2s both}
@keyframes hr-grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.hr-ticks{display:block;position:relative;height:28px;margin-top:6px;font-size:13px;color:var(--mute)}
.hr-ticks span{display:block;position:absolute;top:0}
.hr-note{font-size:13px;color:var(--mute);margin-top:2px}
.hr-pair{display:grid;grid-template-columns:1fr 1fr;margin-top:36px;border-top:1px solid var(--line)}
.hr-pair div{display:block;padding:20px 24px 0 0}
.hr-pair div+div{padding-left:24px;border-left:1px solid var(--line)}
.hr-pair b{display:block;font-size:clamp(24px,3.4vw,32px);line-height:1.2;font-weight:800;letter-spacing:-.02em}
.hr-pair b i{font-style:normal;color:var(--blue-deep)}
.hr-pair p{font-size:14px;color:var(--mute);margin-top:4px}
.hr-sec{display:block;padding:64px 0;border-top:1px solid var(--line)}
.hr-h2{font-size:clamp(23px,3.4vw,28px);line-height:1.35;font-weight:750;letter-spacing:-.018em;max-width:24em}
.hr-claim{margin-top:10px;color:var(--mute);max-width:36em}
.hr-period{display:inline-block;margin-top:10px;font-size:14px;font-weight:600;color:var(--blue-deep)}
.hr-body{margin-top:18px;max-width:38em}
.hr-cmp-list{margin-top:32px;border-top:1px solid var(--line)}
.hr-cmp{display:grid;grid-template-columns:minmax(0,220px) minmax(0,1fr) 150px;gap:8px 28px;align-items:center;padding:20px 0;border-bottom:1px solid var(--line)}
.hr-cmp-name{font-weight:700}
.hr-cmp-name small{display:block;font-size:13px;font-weight:400;color:var(--mute);line-height:1.5}
.hr-track{display:block;height:12px;margin:3px 0}
.hr-fill{display:block;height:12px;border-radius:0 3px 3px 0}
.hr-fill-b{background:var(--gray)}
.hr-fill-a{background:var(--blue)}
.hr-cmp-val{font-weight:750;text-align:right;white-space:nowrap}
.hr-cmp-val i{font-style:normal;color:var(--blue-deep)}
.hr-proj{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:40px;margin-top:28px;align-items:start}
.hr-facts{display:block;border-top:2px solid var(--ink)}
.hr-facts div{display:grid;grid-template-columns:96px minmax(0,1fr);gap:16px;padding:16px 0;border-bottom:1px solid var(--line)}
.hr-facts dt{font-weight:750;color:var(--blue-deep)}
.hr-facts dd{margin:0}
.hr-side{display:block;background:var(--tint);padding:22px 22px 20px;border-radius:6px}
.hr-side div{display:block;padding:0 0 16px}
.hr-side div+div{padding:16px 0 0;border-top:1px solid #cfe0fb}
.hr-side b{display:block;font-size:26px;line-height:1.2;font-weight:800;letter-spacing:-.02em}
.hr-side b i{font-style:normal;color:var(--blue-deep)}
.hr-side p{font-size:14px;color:var(--mute)}
.hr-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;margin-top:36px;counter-reset:s}
.hr-step{display:block;position:relative;padding:34px 20px 0 0}
.hr-step::before{content:'';display:block;position:absolute;left:0;right:0;top:11px;height:2px;background:var(--line)}
.hr-step::after{counter-increment:s;content:counter(s);display:block;position:absolute;left:0;top:0;width:24px;height:24px;border-radius:50%;background:var(--blue);color:#fff;font-size:13px;font-weight:700;line-height:24px;text-align:center}
.hr-step:last-child::before{right:auto;width:0}
.hr-step h3{font-size:17px;font-weight:750}
.hr-step p{font-size:15px;color:#2b3745;margin-top:6px;line-height:1.65}
.hr-results{display:flex;flex-wrap:wrap;gap:12px 40px;margin-top:36px;padding-top:20px;border-top:1px solid var(--line)}
.hr-results div{display:block}
.hr-results b{display:block;font-size:24px;line-height:1.3;font-weight:800}
.hr-results b i{font-style:normal;color:var(--blue-deep)}
.hr-results p{font-size:14px;color:var(--mute)}
.hr-band{display:block;background:var(--tint);padding:56px 0;border-top:0}
.hr-band .hr-h2{max-width:20em}
.hr-band .hr-body{border-left:3px solid var(--blue);padding-left:18px}
.hr-stack{display:block;margin-top:28px;border-top:2px solid var(--ink)}
.hr-stack div{display:grid;grid-template-columns:180px minmax(0,1fr);gap:16px;padding:16px 0;border-bottom:1px solid var(--line)}
.hr-stack dt{font-weight:750}
.hr-stack dd{margin:0;color:#2b3745}
.hr-two{display:grid;grid-template-columns:1fr 1fr;gap:0;margin-top:28px}
.hr-two div{display:block;padding:0 32px 0 0}
.hr-two div+div{padding:0 0 0 32px;border-left:1px solid var(--line)}
.hr-two h3{font-size:18px;font-weight:750}
.hr-two p{margin-top:8px;color:#2b3745;font-size:15.5px}
.hr-job{display:grid;grid-template-columns:170px minmax(0,1fr);gap:8px 32px;margin-top:28px}
.hr-job time{font-weight:700;color:var(--blue-deep)}
.hr-job h3{font-size:18px;font-weight:750}
.hr-job p{margin-top:6px;color:#2b3745;max-width:38em}
.hr-ev{display:block;margin-top:24px;border-top:2px solid var(--ink)}
.hr-ev li{display:grid;grid-template-columns:minmax(0,1fr) 120px;gap:4px 24px;padding:16px 0;border-bottom:1px solid var(--line)}
.hr-ev h3{font-size:16px;font-weight:700}
.hr-ev p{grid-column:1;font-size:14.5px;color:var(--mute);line-height:1.65}
.hr-ev span{display:block;grid-column:2;grid-row:1;font-size:13px;color:var(--blue-deep);font-weight:600;text-align:right}
.hr-end{display:block;height:48px}
@media (max-width:760px){.hr-hero{padding:48px 0 40px}.hr-sec{padding:48px 0}.hr-bar{height:46px}.hr-cmp{grid-template-columns:1fr;gap:6px}.hr-cmp-val{text-align:left}.hr-proj{grid-template-columns:1fr;gap:28px}.hr-facts div{grid-template-columns:1fr;gap:2px}.hr-steps{grid-template-columns:1fr}.hr-step{padding:0 0 22px 40px}.hr-step::before{left:11px;right:auto;top:0;bottom:0;width:2px;height:auto}.hr-step:last-child::before{width:0}.hr-stack div{grid-template-columns:1fr;gap:2px}.hr-two{grid-template-columns:1fr;gap:24px}.hr-two div,.hr-two div+div{padding:0;border-left:0}.hr-job{grid-template-columns:1fr;gap:4px}.hr-ev li{grid-template-columns:1fr}.hr-ev span{grid-column:1;grid-row:auto;text-align:left}.hr-pair div{padding-right:12px}.hr-pair div+div{padding-left:14px}.hr-pair p{font-size:13px}}
@media (prefers-reduced-motion:reduce){.hr-bar-before,.hr-bar-after{animation:none}}
.hr-page a:focus-visible,.hr-page details:focus-visible{outline:3px solid var(--blue);outline-offset:3px}
